            "Safe observation means gathering information without entering restricted areas, touching animals, using equipment or moving around the farm unless directed by the teacher. Farms contain changing hazards, so students must remain aware of gates, fences, tools, vehicles, animals, surfaces and other infrastructure. Careful observation begins by following instructions, staying within approved areas and reporting anything that appears unsafe.",
            "Useful agricultural observations connect visible evidence with a possible purpose. A plant may have leaves, stems, flowers, fruit, seeds or other parts that suggest how it could be used. An animal’s visible characteristics may help indicate its breed or the type of product associated with it. Infrastructure also provides evidence. Fences, shelters, yards, garden beds, watering systems and storage areas can suggest how a farm space supports a particular enterprise. A strong observation explains both what is present and why it may be useful.",
