          "id": "7.1",
          "title": "Water uptake and transport in plants",
          "theory": [
            "Plants need water for growth, photosynthesis, transport and maintaining cell structure. Water enters mainly through the roots. Tiny extensions called root hairs increase the surface area available for absorption from the growing medium. Water can contain dissolved mineral nutrients, so uptake helps supply materials needed by different parts of the plant.",
            "After entering the roots, water moves upwards through xylem . Xylem is specialised transport tissue that carries water and dissolved minerals from the roots towards stems and leaves. Water movement is linked with transpiration, which is the loss of water vapour mainly from leaf surfaces. As water leaves the plant, it helps create movement through the xylem, drawing more water upwards. Environmental conditions can influence transpiration, so the rate of water movement is not always the same.",
            "A coloured-water celery investigation can provide visible evidence of transport through plant tissue. An observation might describe coloured areas appearing within the stem or leaf veins. An explanation goes further by linking that evidence to water movement through xylem. These statements should remain separate: observations report what can be seen, while explanations use plant knowledge to interpret the evidence. One investigation supports an explanation but does not show every detail of water transport. Strong conclusions connect the recorded evidence with the roles of root hairs, xylem and transpiration without claiming more than the observations support."
          ],
          "takeaways": [
            "The programme covers root hairs, xylem and transpiration.",
            "Students may observe coloured-water uptake in celery and record evidence.",
            "An observation should be separated from an explanation of the process."
          ],
