          "model": "Drought creates a production challenge because limited water can reduce plant growth, change soil conditions and increase production risk. A grower may need to reconsider crop choice, water use and expected output. Possible responses should be compared for cost, practicality and sustainability. Current drought claims must be supported by dated authoritative evidence, and no single strategy can remove all risk.",
