      "project": "Year 9 Agriculture",
      "projectModule": 19,
      "cadence": "Term 4 · Weeks 7-10",
      "title": "Poultry markets, health and enterprise evaluation",
      "summary": "Learn Broiler and Layer Markets and Gross Margins and Poultry Health, then apply the ideas through knowledge checks and written evidence.",
